'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import type { Role, Employee, SectionKey } from '@/types/hrms';

interface HrmsContextValue {
  roles: Role[];
  employees: Employee[];
  viewAsEmployeeId: string | null;
  setViewAsEmployeeId: (id: string | null) => void;
  addRole: (role: Omit<Role, 'id' | 'createdAt'>) => void;
  updateRole: (id: string, updates: Partial<Omit<Role, 'id' | 'createdAt'>>) => void;
  deleteRole: (id: string) => void;
  addEmployee: (emp: Omit<Employee, 'id' | 'createdAt'>) => string;
  updateEmployee: (id: string, updates: Partial<Omit<Employee, 'id' | 'createdAt'>>) => void;
  deleteEmployee: (id: string) => void;
  getRoleById: (id: string) => Role | undefined;
  getEmployeeById: (id: string) => Employee | undefined;
}

const HrmsContext = createContext<HrmsContextValue | null>(null);

const SEED_ROLES: Role[] = [
  {
    id: 'role-admin',
    name: 'Administrator',
    description: 'Full access to all sections',
    permissions: ['dashboard', 'reservations', 'guests', 'accommodations', 'dining', 'events', 'gallery', 'blogs', 'inventory', 'reports', 'hrms', 'settings'],
    createdAt: new Date().toISOString(),
  },
  {
    id: 'role-receptionist',
    name: 'Receptionist',
    description: 'Front desk operations',
    permissions: ['dashboard', 'reservations', 'guests'],
    createdAt: new Date().toISOString(),
  },
  {
    id: 'role-manager',
    name: 'Manager',
    description: 'Operational oversight across all departments',
    permissions: ['dashboard', 'reservations', 'guests', 'accommodations', 'dining', 'events', 'reports'],
    createdAt: new Date().toISOString(),
  },
  {
    id: 'role-housekeeper',
    name: 'Housekeeping',
    description: 'Room and facility management',
    permissions: ['dashboard', 'accommodations'],
    createdAt: new Date().toISOString(),
  },
];

export function HrmsProvider({ children }: { children: React.ReactNode }) {
  const [roles, setRoles] = useState<Role[]>(SEED_ROLES);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [viewAsEmployeeId, setViewAsEmployeeId] = useState<string | null>(null);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    try {
      const savedRoles = localStorage.getItem('hrms_roles');
      const savedEmployees = localStorage.getItem('hrms_employees');
      if (savedRoles) setRoles(JSON.parse(savedRoles));
      if (savedEmployees) setEmployees(JSON.parse(savedEmployees));
    } catch {
      // ignore parse errors
    }
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (hydrated) localStorage.setItem('hrms_roles', JSON.stringify(roles));
  }, [roles, hydrated]);

  useEffect(() => {
    if (hydrated) localStorage.setItem('hrms_employees', JSON.stringify(employees));
  }, [employees, hydrated]);

  const addRole = (role: Omit<Role, 'id' | 'createdAt'>) => {
    setRoles(prev => [...prev, { ...role, id: `role-${Date.now()}`, createdAt: new Date().toISOString() }]);
  };

  const updateRole = (id: string, updates: Partial<Omit<Role, 'id' | 'createdAt'>>) => {
    setRoles(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const deleteRole = (id: string) => {
    setRoles(prev => prev.filter(r => r.id !== id));
  };

  const addEmployee = (emp: Omit<Employee, 'id' | 'createdAt'>): string => {
    const id = `emp-${Date.now()}`;
    setEmployees(prev => [...prev, { ...emp, id, createdAt: new Date().toISOString() }]);
    return id;
  };

  const updateEmployee = (id: string, updates: Partial<Omit<Employee, 'id' | 'createdAt'>>) => {
    setEmployees(prev => prev.map(e => e.id === id ? { ...e, ...updates } : e));
  };

  const deleteEmployee = (id: string) => {
    setEmployees(prev => prev.filter(e => e.id !== id));
    if (viewAsEmployeeId === id) setViewAsEmployeeId(null);
  };

  return (
    <HrmsContext.Provider value={{
      roles,
      employees,
      viewAsEmployeeId,
      setViewAsEmployeeId,
      addRole,
      updateRole,
      deleteRole,
      addEmployee,
      updateEmployee,
      deleteEmployee,
      getRoleById: (id) => roles.find(r => r.id === id),
      getEmployeeById: (id) => employees.find(e => e.id === id),
    }}>
      {children}
    </HrmsContext.Provider>
  );
}

export function useHrms() {
  const ctx = useContext(HrmsContext);
  if (!ctx) throw new Error('useHrms must be used within HrmsProvider');
  return ctx;
}
